int ccs811_power_up (ccs811_t *dev)
{
    ASSERT_PARAM(dev != NULL);

    if (dev->params.wake_pin != GPIO_UNDEF) {
        DEBUG_DEV("Setting nWAKE pin low", dev);
        gpio_clear(dev->params.wake_pin);
    }

    return ccs811_set_mode(dev, dev->params.mode);
}

